const inp = $('Normalize Input').first().json;
const raw = String(($input.first().json.source_body || '')).replace(/\r/g, '').trim();
const words = raw.split(/\s+/).filter(Boolean);
const MAX_WORDS = 9000;
const body = words.slice(0, MAX_WORDS).join(' ');
return [{ json: {
  run_id: inp.run_id,
  source_title: inp.source_title,
  source_type: inp.source_type,
  source_url: inp.source_url,
  voice_notes: inp.voice_notes,
  source_body: words.length > MAX_WORDS ? body : raw,
  source_word_count: words.length,
  truncated: words.length > MAX_WORDS
} }];

