Read the source and return a content brief as JSON only, no prose, no code fences, with exactly these keys:
{"core_message": "one sentence", "audience": "who this is for", "key_points": [{"point": "...", "evidence": "detail from the source that supports it"}], "facts": ["every number, name or claim worth reusing, copied exactly as written in the source"], "quotable_lines": ["short lines from the source that work on their own"], "hook_angles": ["3 different opening angles"], "lesson": "the one non-obvious takeaway", "seo_keyword": "a realistic search phrase", "cta": "a natural next step for the reader"}
Use 4 to 6 key_points. Only include what the source supports.

parameters.jsCode:
const src = $('Prepare Source').first().json;
const res = $input.first().json;
const text = Array.isArray(res.content) ? res.content.map(function (c) { return c.text || ''; }).join('') : (res.text || '');
let brief;
let briefParsed = true;
try {
  brief = JSON.parse(text.replace(/^\s*\x60\x60\x60(json)?/i, '').replace(/\x60\x60\x60\s*$/, '').trim());
} catch (e) {
  brief = { raw_brief: text };
  briefParsed = false;
}
const briefStr = JSON.stringify(brief, null, 2);
const usage = res.usage || {};
const details = usage.output_tokens_details || {};

const rules = [
  'Use only facts, numbers and names that appear in the SOURCE or BRIEF. Never invent results, metrics, people or quotes.',
  'If a detail is needed but missing, write [CHECK: what is missing] instead of guessing.',
  'Write in this voice: ' + src.voice_notes,
  'Never use these words: game-changer, revolutionize, unlock, supercharge, delve, leverage, cutting-edge, seamless, in today\'s fast-paced world.',
  'Output only the deliverable. No preamble, no notes to the editor.'
].join('\n- ');

const channels = [
  { channel: 'linkedin_post', label: 'LinkedIn post', spec: 'A LinkedIn post of 150 to 250 words. Line 1 is a hook of at most 15 words built on a result, a surprise or a strong opinion. Then 2 lines of context. Then a short "What I built" or "What happened" section using → arrows. Then one PM-style lesson. End with one question that invites comments. At most 3 hashtags on the last line. No links in the body.' },
  { channel: 'x_thread', label: 'X thread', spec: 'An X thread of 5 to 8 posts. Separate posts with a line containing only ---. Each post must be under 270 characters. Post 1 is the hook and must stand alone. Last post sums up the lesson. No hashtags. Do not number the posts.' },
  { channel: 'newsletter_section', label: 'Newsletter section', spec: 'A newsletter section of 180 to 300 words. First line: "Subject: " followed by a subject line under 60 characters. Second line: a ## heading. Then short paragraphs, one concrete example from the source, and a one-line takeaway in bold at the end.' },
  { channel: 'short_video_script', label: 'Short video script', spec: 'A 45 to 60 second vertical video script, 110 to 170 spoken words. Use these labelled parts on their own lines: HOOK (0-3s), SETUP, PAYOFF, CTA. Under each part write the spoken line, and add [ON SCREEN: ...] cues on separate lines. The hook must work with the sound off.' },
  { channel: 'seo_blog_draft', label: 'SEO blog draft', spec: 'An SEO blog draft of 700 to 1100 words in markdown. First three lines exactly: "Title: ...", "Meta description: ..." (under 155 characters), "Target keyword: ..." (use the brief seo_keyword). Then the article with one # H1, at least three ## H2 sections, a short FAQ with 2 questions, and a conclusion. Use the target keyword in the H1 and in the first 100 words.' }
];

return channels.map(function (c) {
  return { json: {
    run_id: src.run_id,
    source_title: src.source_title,
    source_type: src.source_type,
    channel: c.channel,
    channel_label: c.label,
    brief_parsed: briefParsed,
    brief_stop_reason: res.stop_reason || '',
    brief_input_tokens: usage.input_tokens || 0,
    brief_output_tokens: usage.output_tokens || 0,
    brief_thinking_tokens: details.thinking_tokens || 0,
    system_prompt: 'You turn one long-form source into a single channel-ready draft. Rules:\n- ' + rules,
    user_prompt: 'CHANNEL: ' + c.label + '\nSPEC: ' + c.spec + '\n\nBRIEF:\n' + briefStr + '\n\nSOURCE (' + src.source_title + '):\n<source>\n' + src.source_body + '\n</source>\n\nWrite the ' + c.label + ' now.'
  } };
});

const drafts = $input.all();
const jobs = $('Plan Channel Jobs').all();
const src = $('Prepare Source').first().json;
const sourceText = (src.source_body || '').replace(/,/g, '').toLowerCase();
const banned = ['game-changer', 'game changer', 'revolutioniz', 'unlock', 'supercharge', 'delve', 'leverage', 'cutting-edge', 'seamless', 'fast-paced world'];

function textOf(j) {
  if (Array.isArray(j.content)) return j.content.map(function (c) { return c.text || ''; }).join('').trim();
  return String(j.merged_response || j.text || j.output || '').trim();
}
function wc(s) { return s.split(/\s+/).filter(Boolean).length; }

return drafts.map(function (d, i) {
  const job = jobs[i].json;
  const draft = textOf(d.json);
  const words = wc(draft);
  const notes = [];
  const lower = draft.toLowerCase();

  banned.forEach(function (b) { if (lower.indexOf(b) !== -1) notes.push('banned word: ' + b); });
  if (/\[check:/i.test(draft)) notes.push('has [CHECK: ...] placeholders to resolve');
  if (draft.indexOf('\u2014') !== -1) notes.push('contains em dash');

  const nums = (draft.match(/\d[\d,.]*%?/g) || []).map(function (n) { return n.replace(/,/g, '').replace(/[.]$/, ''); });
  const unknown = nums.filter(function (n) {
    const v = parseFloat(n);
    if (!isNaN(v) && v <= 10 && n.indexOf('%') === -1) return false;
    return sourceText.indexOf(n.toLowerCase()) === -1 && sourceText.indexOf(n.replace('%', '').toLowerCase()) === -1;
  });
  if (unknown.length) notes.push('numbers not found in source: ' + Array.from(new Set(unknown)).join(', '));

  if (job.channel === 'linkedin_post') {
    if (words < 120 || words > 270) notes.push('length ' + words + ' words (target 150-250)');
    const tags = (draft.match(/#\w+/g) || []).length;
    if (tags > 3) notes.push(tags + ' hashtags (max 3)');
    if (/https?:\/\//.test(draft)) notes.push('link in body');
    if (draft.split('\n')[0].split(/\s+/).length > 18) notes.push('hook line too long');
  }
  if (job.channel === 'x_thread') {
    const posts = draft.split(/\n\s*---\s*\n/).map(function (p) { return p.trim(); }).filter(Boolean);
    if (posts.length < 5 || posts.length > 8) notes.push(posts.length + ' posts (target 5-8)');
    posts.forEach(function (p, k) { if (p.length > 280) notes.push('post ' + (k + 1) + ' is ' + p.length + ' chars'); });
  }
  if (job.channel === 'newsletter_section') {
    if (!/^subject:/i.test(draft)) notes.push('missing Subject line');
    if (words < 160 || words > 330) notes.push('length ' + words + ' words (target 180-300)');
  }
  if (job.channel === 'short_video_script') {
    ['HOOK', 'SETUP', 'PAYOFF', 'CTA'].forEach(function (p) { if (draft.indexOf(p) === -1) notes.push('missing ' + p); });
    const spoken = draft.split('\n').filter(function (l) { return l.trim() && !/^\s*\[ON SCREEN/i.test(l) && !/^\s*\**(HOOK|SETUP|PAYOFF|CTA)/i.test(l); }).join(' ');
    const sw = wc(spoken);
    if (sw < 100 || sw > 185) notes.push('spoken length ' + sw + ' words (target 110-170)');
  }
  if (job.channel === 'seo_blog_draft') {
    if (!/^title:/im.test(draft)) notes.push('missing Title');
    const meta = (draft.match(/^meta description:\s*(.*)$/im) || [])[1] || '';
    if (!meta) notes.push('missing meta description');
    else if (meta.length > 160) notes.push('meta description ' + meta.length + ' chars');
    const h2 = (draft.match(/^## /gm) || []).length;
    if (h2 < 3) notes.push('only ' + h2 + ' H2 sections');
    if (words < 650 || words > 1200) notes.push('length ' + words + ' words (target 700-1100)');
  }

  return { json: {
    run_id: job.run_id,
    source_title: job.source_title,
    source_type: job.source_type,
    channel: job.channel,
    draft: draft,
    word_count: words,
    gate_passed: notes.length === 0,
    gate_notes: notes.length ? notes.join('; ') : 'passed',
    status: 'needs_review',
    final_text: '',
    input_tokens: (d.json.usage && d.json.usage.input_tokens) || 0,
    output_tokens: (d.json.usage && d.json.usage.output_tokens) || 0,
    thinking_tokens: (d.json.usage && d.json.usage.output_tokens_details && d.json.usage.output_tokens_details.thinking_tokens) || 0,
    model: d.json.model || ''
  } };
});

const rows = $('Quality Gate').all().map(function (r) { return r.json; });
const job = $('Plan Channel Jobs').first().json;
function sum(k) { return rows.reduce(function (a, r) { return a + (r[k] || 0); }, 0); }
return [{ json: {
  run_id: job.run_id,
  source_title: job.source_title,
  brief_parsed: job.brief_parsed,
  brief_stop_reason: job.brief_stop_reason,
  drafts: rows.length,
  passed_gate: rows.filter(function (r) { return r.gate_passed; }).length,
  flagged: rows.filter(function (r) { return !r.gate_passed; }).map(function (r) { return r.channel + ': ' + r.gate_notes; }),
  brief_input_tokens: job.brief_input_tokens,
  brief_output_tokens: job.brief_output_tokens,
  brief_thinking_tokens: job.brief_thinking_tokens,
  draft_input_tokens: sum('input_tokens'),
  draft_output_tokens: sum('output_tokens'),
  draft_thinking_tokens: sum('thinking_tokens'),
  llm_calls: rows.length + 1
} }];
